// slides/compile.js
const pptxgen = require('pptxgenjs');
const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';

const theme = {
  primary: "03045e",    // deep navy - titles
  secondary: "0077b6",  // medium blue - body/accents
  accent: "00b4d8",     // bright cyan - highlights
  light: "90e0ef",      // light blue - subtle elements
  bg: "caf0f8"          // very light blue - background
};

// Import all 9 slides
for (let i = 1; i <= 9; i++) {
  const num = String(i).padStart(2, '0');
  try {
    const slideModule = require(`./slide-${num}.js`);
    slideModule.createSlide(pres, theme);
    console.log(`Added slide ${num}`);
  } catch (err) {
    console.error(`Error loading slide-${num}.js:`, err.message);
  }
}

pres.writeFile({ fileName: './output/final_deck.pptx' })
  .then(() => console.log('Created ./output/final_deck.pptx'))
  .catch(err => console.error('Error writing file:', err));

