// SLIDE 5: Length-Adaptive GAE - Dynamic λ Adjustment for Variable Response Lengths

const theme = {
  primary: "03045e",    // deep navy - titles
  secondary: "0077b6",  // medium blue - body/accents
  accent: "00b4d8",     // bright cyan - highlights
  light: "90e0ef",      // light blue - subtle elements
  bg: "caf0f8"          // very light blue - background
};

// ============================================================
// createSlide(pres, slide, theme) - Adds Slide 5 to presentation
// ============================================================
function createSlide(pres, slide, theme) {
  // Background
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Length-Adaptive GAE: Dynamic \u03BB Adjustment for Variable Response Lengths", {
    x: 0.5, y: 0.25, w: 9, h: 0.7,
    fontSize: 22, fontFace: "Arial", bold: true,
    color: theme.primary, align: "left", valign: "middle"
  });

  // Subtitle
  slide.addText("Novel technique for balancing bias-variance tradeoff across response lengths", {
    x: 0.5, y: 0.9, w: 9, h: 0.35,
    fontSize: 13, fontFace: "Arial", bold: false,
    color: theme.secondary, align: "left", valign: "middle"
  });

  // --- LEFT COLUMN: Key Concept Section ---
  // Section header
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.4, w: 0.08, h: 0.4,
    fill: { color: theme.accent }, line: { color: theme.accent, width: 0 }
  });
  slide.addText("\u03BB in GAE Controls Bias-Variance Tradeoff", {
    x: 0.7, y: 1.4, w: 4.3, h: 0.4,
    fontSize: 14, fontFace: "Arial", bold: true,
    color: theme.primary, align: "left", valign: "middle"
  });

  // Lambda explanation bullets
  slide.addText([
    { text: "\u03BB \u2192 0: Lower variance, higher bias", options: { bullet: true, breakLine: true } },
    { text: "    Favors value estimate from bootstrapping", options: { breakLine: true } },
    { text: "\u03BB \u2192 1: Higher variance, lower bias", options: { bullet: true, breakLine: true } },
    { text: "    Favors Monte Carlo return estimates", options: { breakLine: true } }
  ], {
    x: 0.7, y: 1.85, w: 4.3, h: 1.1,
    fontSize: 11, fontFace: "Arial", bold: false,
    color: theme.secondary, align: "left", valign: "top"
  });

  // --- LEFT COLUMN: Novel Adaptation Section ---
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 3.05, w: 0.08, h: 0.4,
    fill: { color: theme.accent }, line: { color: theme.accent, width: 0 }
  });
  slide.addText("Novel Adaptation: \u03BB Varies with Response Length", {
    x: 0.7, y: 3.05, w: 4.3, h: 0.4,
    fontSize: 14, fontFace: "Arial", bold: true,
    color: theme.primary, align: "left", valign: "middle"
  });

  slide.addText([
    { text: "Short responses \u2192 Lower \u03BB", options: { bullet: true, breakLine: true } },
    { text: "    Lower variance is safe for short horizons", options: { breakLine: true } },
    { text: "Long responses \u2192 Higher \u03BB", options: { bullet: true, breakLine: true } },
    { text: "    Need lower bias for long horizon accumulation", options: { breakLine: true } }
  ], {
    x: 0.7, y: 3.5, w: 4.3, h: 1.0,
    fontSize: 11, fontFace: "Arial", bold: false,
    color: theme.secondary, align: "left", valign: "top"
  });

  // Formula box
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.7, y: 4.55, w: 4.3, h: 0.55,
    fill: { color: theme.light, transparency: 40 },
    line: { color: theme.accent, width: 1.5 },
    rectRadius: 0.08
  });
  slide.addText("\u03BB = f(length, horizon) — adaptive weighting", {
    x: 0.7, y: 4.55, w: 4.3, h: 0.55,
    fontSize: 12, fontFace: "Arial", bold: true,
    color: theme.primary, align: "center", valign: "middle"
  });

  // --- RIGHT COLUMN: Visual Diagram ---
  // Diagram container
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 5.3, y: 1.4, w: 4.2, h: 3.7,
    fill: { color: "FFFFFF" },
    line: { color: theme.light, width: 1 },
    rectRadius: 0.1,
    shadow: { type: "outer", color: "000000", blur: 8, offset: 3, angle: 135, opacity: 0.08 }
  });

  slide.addText("Length-Adaptive \u03BB Visualization", {
    x: 5.4, y: 1.5, w: 4, h: 0.35,
    fontSize: 12, fontFace: "Arial", bold: true,
    color: theme.primary, align: "center", valign: "middle"
  });

  // Short response box with LOW lambda
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.6, y: 2.0, w: 1.4, h: 0.8,
    fill: { color: theme.light },
    line: { color: theme.secondary, width: 1 }
  });
  slide.addText("Short\nResponse", {
    x: 5.6, y: 2.0, w: 1.4, h: 0.8,
    fontSize: 9, fontFace: "Arial", bold: false,
    color: theme.primary, align: "center", valign: "middle"
  });

  // Arrow and lambda label for short
  slide.addText("\u03BB = 0.1", {
    x: 7.1, y: 2.15, w: 0.8, h: 0.3,
    fontSize: 10, fontFace: "Arial", bold: true,
    color: theme.secondary, align: "center", valign: "middle"
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.9, y: 2.15, w: 0.8, h: 0.35,
    fill: { color: theme.secondary },
    line: { color: theme.secondary, width: 0 }
  });
  slide.addText("Low Var", {
    x: 7.9, y: 2.15, w: 0.8, h: 0.35,
    fontSize: 8, fontFace: "Arial", bold: true,
    color: "FFFFFF", align: "center", valign: "middle"
  });

  // --- Middle arrow area ---
  // Lambda formula indicator
  slide.addText("\u03BB = f(response_length)", {
    x: 5.6, y: 2.95, w: 3.6, h: 0.3,
    fontSize: 10, fontFace: "Arial", bold: false, italic: true,
    color: theme.accent, align: "center", valign: "middle"
  });

  // Vertical relationship line
  slide.addShape(pres.shapes.LINE, {
    x: 6.8, y: 2.95, w: 0, h: 0.45,
    line: { color: theme.accent, width: 1.5, dashType: "dash" }
  });

  // Long response box with HIGH lambda
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.6, y: 3.55, w: 2.0, h: 1.0,
    fill: { color: theme.light },
    line: { color: theme.accent, width: 2 }
  });
  slide.addText("Long\nResponse", {
    x: 5.6, y: 3.55, w: 2.0, h: 1.0,
    fontSize: 10, fontFace: "Arial", bold: false,
    color: theme.primary, align: "center", valign: "middle"
  });

  // Arrow and lambda label for long
  slide.addText("\u03BB = 0.95", {
    x: 7.7, y: 3.85, w: 0.8, h: 0.3,
    fontSize: 10, fontFace: "Arial", bold: true,
    color: theme.accent, align: "center", valign: "middle"
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 8.5, y: 3.7, w: 0.85, h: 0.6,
    fill: { color: theme.accent },
    line: { color: theme.accent, width: 0 }
  });
  slide.addText("Low Bias", {
    x: 8.5, y: 3.7, w: 0.85, h: 0.6,
    fontSize: 8, fontFace: "Arial", bold: true,
    color: "FFFFFF", align: "center", valign: "middle"
  });

  // Scale legend
  slide.addText("Adaptation Scale:", {
    x: 5.6, y: 4.65, w: 1.2, h: 0.3,
    fontSize: 8, fontFace: "Arial", bold: false,
    color: theme.secondary, align: "left", valign: "middle"
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.8, y: 4.68, w: 2.5, h: 0.2,
    fill: { color: theme.light },
    line: { color: theme.secondary, width: 0.5 }
  });
  slide.addText("0", {
    x: 6.7, y: 4.65, w: 0.3, h: 0.25,
    fontSize: 7, fontFace: "Arial", bold: false,
    color: theme.secondary, align: "center", valign: "middle"
  });
  slide.addText("1", {
    x: 9.2, y: 4.65, w: 0.3, h: 0.25,
    fontSize: 7, fontFace: "Arial", bold: false,
    color: theme.secondary, align: "center", valign: "middle"
  });
  slide.addText("\u03BB", {
    x: 8.9, y: 4.65, w: 0.4, h: 0.25,
    fontSize: 9, fontFace: "Arial", bold: true,
    color: theme.primary, align: "center", valign: "middle"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }, line: { color: theme.accent, width: 0 }
  });
  slide.addText("5", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial", bold: true,
    color: "FFFFFF", align: "center", valign: "middle"
  });
}

// ============================================================
// slideConfig - Metadata for this slide
// ============================================================
const slideConfig = {
  id: 5,
  title: "Length-Adaptive GAE",
  description: "Dynamic λ adjustment for variable response lengths",
  theme: "VAPO Technical Presentation"
};

module.exports = { createSlide, slideConfig };

// ============================================================
// STANDALONE PREVIEW
// ============================================================
if (require.main === module) {
  const pptxgen = require("pptxgenjs");
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  const slide = pres.addSlide();
  createSlide(pres, slide, theme);
  pres.writeFile({ fileName: "/app/slides/slide-05-preview.pptx" })
    .then(() => console.log("Preview saved: /app/slides/slide-05-preview.pptx"))
    .catch(err => console.error("Error:", err));
}

