// SLIDE 6: VAPO Main Results - AIME 2024 Performance Comparison

const theme = {
  primary: "03045e",    // deep navy - titles
  secondary: "0077b6",  // medium blue - body/accents
  accent: "00b4d8",     // bright cyan - highlights
  light: "90e0ef",      // light blue - subtle elements
  bg: "caf0f8"          // very light blue - background
};

// ============================================================
// createSlide(pres, slide, theme) - Adds Slide 6 to presentation
// ============================================================
function createSlide(pres, slide, theme) {
  // Background
  slide.background = { color: theme.bg };

  // Title
  slide.addText("VAPO Scores 60 on AIME 2024 \u2014 10+ Points Above DAPO and DeepSeek-R1-Zero", {
    x: 0.5, y: 0.25, w: 9, h: 0.7,
    fontSize: 20, fontFace: "Arial", bold: true,
    color: theme.primary, align: "left", valign: "middle"
  });

  // Subtitle
  slide.addText("Benchmarking results on competition mathematics", {
    x: 0.5, y: 0.9, w: 9, h: 0.3,
    fontSize: 12, fontFace: "Arial", bold: false,
    color: theme.secondary, align: "left", valign: "middle"
  });

  // --- BAR CHART (left side) ---
  const chartData = [{
    name: "AIME 2024 Score",
    labels: ["Vanilla\nPPO", "DeepSeek-R1-Zero\n(Qwen-32B)", "DAPO", "VAPO"],
    values: [5, 47, 50, 60]
  }];

  slide.addChart(pres.charts.BAR, chartData, {
    x: 0.5, y: 1.35, w: 5.5, h: 3.5,
    barDir: "col",
    barGapWidthPct: 80,

    // Colors: VAPO (accent/cyan) highlighted, others secondary blue
    chartColors: [theme.secondary, theme.secondary, theme.secondary, theme.accent],

    // Clean white background for chart area
    chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true },

    // Title
    showTitle: false,

    // Axis styling
    catAxisLabelColor: theme.primary,
    catAxisLabelFontSize: 9,
    catAxisLabelFontFace: "Arial",
    valAxisLabelColor: theme.secondary,
    valAxisLabelFontSize: 9,
    valAxisLabelFontFace: "Arial",
    valAxisMaxVal: 70,
    valAxisMinVal: 0,

    // Grid lines
    valGridLine: { color: theme.light, size: 0.5 },
    catGridLine: { style: "none" },

    // Data labels on bars
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: theme.primary,
    dataLabelFontSize: 11,
    dataLabelFontFace: "Arial",
    dataLabelFontBold: true,

    // Hide legend (single series)
    showLegend: false
  });

  // Chart note below
  slide.addText("AIME 2024 avg@32", {
    x: 0.5, y: 4.85, w: 5.5, h: 0.3,
    fontSize: 10, fontFace: "Arial", bold: false, italic: true,
    color: theme.secondary, align: "center", valign: "middle"
  });

  // --- RIGHT SIDE: Training curve reference ---
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 6.2, y: 1.35, w: 3.3, h: 3.3,
    fill: { color: "FFFFFF" },
    line: { color: theme.light, width: 1 },
    rectRadius: 0.1,
    shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.08 }
  });

  slide.addText("Training Curve", {
    x: 6.3, y: 1.45, w: 3.1, h: 0.35,
    fontSize: 11, fontFace: "Arial", bold: true,
    color: theme.primary, align: "center", valign: "middle"
  });

  slide.addText("Reference: figure_2.jpg", {
    x: 6.3, y: 1.8, w: 3.1, h: 0.25,
    fontSize: 9, fontFace: "Arial", bold: false, italic: true,
    color: theme.secondary, align: "center", valign: "middle"
  });

  // Image placeholder/reference area
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.4, y: 2.1, w: 2.9, h: 2.0,
    fill: { color: theme.light, transparency: 50 },
    line: { color: theme.secondary, width: 0.5, dashType: "dash" }
  });

  slide.addImage({
    path: "/app/benchmark/assets/figure_2.jpg",
    x: 6.4, y: 2.1, w: 2.9, h: 2.0,
    sizing: { type: "contain", w: 2.9, h: 2.0 }
  });

  // Key insight box below image
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.4, y: 4.15, w: 2.9, h: 0.4,
    fill: { color: theme.accent },
    line: { color: theme.accent, width: 0 }
  });
  slide.addText("VAPO outperforms across all training steps", {
    x: 6.4, y: 4.15, w: 2.9, h: 0.4,
    fontSize: 9, fontFace: "Arial", bold: true,
    color: "FFFFFF", align: "center", valign: "middle"
  });

  // --- Performance summary callout ---
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: 5.2, w: 5.5, h: 0.35,
    fill: { color: theme.primary, transparency: 10 },
    line: { color: theme.primary, width: 0 },
    rectRadius: 0.05
  });
  slide.addText("+55 pts vs Vanilla PPO  |  +13 pts vs DAPO  |  +10 pts vs DeepSeek-R1-Zero", {
    x: 0.5, y: 5.2, w: 5.5, h: 0.35,
    fontSize: 10, fontFace: "Arial", bold: true,
    color: theme.primary, align: "center", valign: "middle"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }, line: { color: theme.accent, width: 0 }
  });
  slide.addText("6", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial", bold: true,
    color: "FFFFFF", align: "center", valign: "middle"
  });
}

// ============================================================
// slideConfig - Metadata for this slide
// ============================================================
const slideConfig = {
  id: 6,
  title: "Main Results - AIME 2024",
  description: "VAPO achieves 60 on AIME 2024, outperforming DAPO and DeepSeek-R1-Zero",
  theme: "VAPO Technical Presentation"
};

module.exports = { createSlide, slideConfig };

